import{_ as a,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"68. 环境变量","description":"The Little Book of C 中文版 — 68. 环境变量","frontmatter":{"title":"68. 环境变量","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","07-贴近系统","中文"],"description":"The Little Book of C 中文版 — 68. 环境变量","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":68,"sidebarWeight":68,"alternateZh":"/posts/c教程/zh-CN/07-贴近系统/068-Environment Variables","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/068-Environment Variables"},"headers":[],"relativePath":"posts/c教程/zh-CN/07-贴近系统/068-Environment Variables.md","filePath":"posts/c教程/zh-CN/07-贴近系统/068-Environment Variables.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/07-贴近系统/068-Environment Variables.md"};function i(l,s,o,c,d,u){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>[English version](/posts/c教程/en-US/07-Working Close to the System/068-Environment Variables)</p><p>Unix 中的每个程序都会继承一组称为环境变量的键值对。它们存储有关您的 shell、系统配置和运行时行为的信息，例如您的用户名、主目录和编译器路径。</p><p>C 使您能够完全控制直接读取、修改和定义这些变量。</p><h4 id="步骤-1-什么是环境变量" tabindex="-1">步骤 1. 什么是环境变量？ <a class="header-anchor" href="#步骤-1-什么是环境变量" aria-label="Permalink to &quot;步骤 1. 什么是环境变量？&quot;">​</a></h4><p>环境变量是以下形式的字符串：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KEY=VALUE</span></span></code></pre></div><p>您可以在 shell 中查看它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printenv</span></span></code></pre></div><p>常见示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HOME=/home/user</span></span>
<span class="line"><span>PATH=/usr/local/bin:/usr/bin:/bin</span></span>
<span class="line"><span>USER=alice</span></span>
<span class="line"><span>LANG=en_US.UTF-8</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span></code></pre></div><p>当您运行每个程序时，这些值将传递给每个程序。</p><h4 id="步骤-2-在-c-中访问环境变量" tabindex="-1">步骤 2. 在 C 中访问环境变量 <a class="header-anchor" href="#步骤-2-在-c-中访问环境变量" aria-label="Permalink to &quot;步骤 2. 在 C 中访问环境变量&quot;">​</a></h4><p>可以使用标准库函数<code>getenv()</code>读取变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const char *path = getenv(&quot;PATH&quot;);</span></span>
<span class="line"><span>    if (path)</span></span>
<span class="line"><span>        printf(&quot;PATH = %s\\n&quot;, path);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;PATH not found.\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATH = /usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</span></span></code></pre></div><p>如果变量不存在，<code>getenv()</code>回报<code>NULL</code>.</p><h4 id="步骤3-设置环境变量" tabindex="-1">步骤3.设置环境变量 <a class="header-anchor" href="#步骤3-设置环境变量" aria-label="Permalink to &quot;步骤3.设置环境变量&quot;">​</a></h4><p>要定义或更改程序内的变量，请使用<code>setenv()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;GREETING&quot;, &quot;Hello from C!&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;%s\\n&quot;, getenv(&quot;GREETING&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>setenv(name, value, overwrite)</code></p><p>-<code>overwrite = 0</code>：不要覆盖现有变量。 -<code>overwrite = 1</code>: 如果存在则替换它。</p><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from C!</span></span></code></pre></div><h4 id="步骤-4-删除环境变量" tabindex="-1">步骤 4. 删除环境变量 <a class="header-anchor" href="#步骤-4-删除环境变量" aria-label="Permalink to &quot;步骤 4. 删除环境变量&quot;">​</a></h4><p>使用<code>unsetenv()</code>删除变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;TEMPVAR&quot;, &quot;temporary&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;Before unset: %s\\n&quot;, getenv(&quot;TEMPVAR&quot;));</span></span>
<span class="line"><span>    unsetenv(&quot;TEMPVAR&quot;);</span></span>
<span class="line"><span>    printf(&quot;After unset: %s\\n&quot;, getenv(&quot;TEMPVAR&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before unset: temporary</span></span>
<span class="line"><span>After unset: (null)</span></span></code></pre></div><h4 id="步骤-5-访问所有环境变量" tabindex="-1">步骤 5. 访问所有环境变量 <a class="header-anchor" href="#步骤-5-访问所有环境变量" aria-label="Permalink to &quot;步骤 5. 访问所有环境变量&quot;">​</a></h4><p>这<code>environ</code>全局变量使您可以访问整个环境列表。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>extern char **environ;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (char **env = environ; *env != NULL; env++) {</span></span>
<span class="line"><span>        printf(&quot;%s\\n&quot;, *env);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这将打印进程中当前活动的所有环境变量。</p><h4 id="步骤-6-将环境变量传递给子进程" tabindex="-1">步骤 6. 将环境变量传递给子进程 <a class="header-anchor" href="#步骤-6-将环境变量传递给子进程" aria-label="Permalink to &quot;步骤 6. 将环境变量传递给子进程&quot;">​</a></h4><p>当你使用<code>fork()</code>和<code>exec()</code>，环境变量由子进程自动继承。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;HELLO&quot;, &quot;world&quot;, 1);</span></span>
<span class="line"><span>    execlp(&quot;printenv&quot;, &quot;printenv&quot;, &quot;HELLO&quot;, NULL);</span></span>
<span class="line"><span>    perror(&quot;execlp&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>world</span></span></code></pre></div><p>您还可以使用提供自定义环境列表<code>execle()</code>或者<code>execve()</code>.</p><h4 id="步骤-7-新程序的自定义环境" tabindex="-1">步骤 7. 新程序的自定义环境 <a class="header-anchor" href="#步骤-7-新程序的自定义环境" aria-label="Permalink to &quot;步骤 7. 新程序的自定义环境&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char *newenv[] = { &quot;MODE=debug&quot;, &quot;VERSION=1.0&quot;, NULL };</span></span>
<span class="line"><span>    execle(&quot;/usr/bin/env&quot;, &quot;env&quot;, NULL, newenv);</span></span>
<span class="line"><span>    perror(&quot;execle&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MODE=debug</span></span>
<span class="line"><span>VERSION=1.0</span></span></code></pre></div><p>新进程只存在这两个变量，其他所有变量都被丢弃。</p><h4 id="步骤-8-为什么环境变量很重要" tabindex="-1">步骤 8. 为什么环境变量很重要 <a class="header-anchor" href="#步骤-8-为什么环境变量很重要" aria-label="Permalink to &quot;步骤 8. 为什么环境变量很重要&quot;">​</a></h4><p>它们是 Unix 设计理念的关键部分：</p><ul><li>程序应该可以配置而无需重新编译。</li><li>环境变量提供全局、进程级配置。</li></ul><p>例如：</p><p>-<code>PATH</code>控制搜索可执行文件的位置。 -<code>HOME</code>定义用户目录。 -<code>LANG</code>定义区域设置。 -<code>LD_LIBRARY_PATH</code>控制动态链接。</p><h4 id="步骤-9-安全注意事项" tabindex="-1">步骤 9. 安全注意事项 <a class="header-anchor" href="#步骤-9-安全注意事项" aria-label="Permalink to &quot;步骤 9. 安全注意事项&quot;">​</a></h4><p>环境变量是自动继承的，因此如果不小心处理它们可能会带来安全风险：</p><ul><li>避免信任环境变量进行身份验证。</li><li>始终验证<code>PATH</code>,<code>HOME</code>， 和<code>TMPDIR</code>.</li><li>使用<code>unsetenv()</code>对于敏感上下文（例如 setuid 程序）。</li></ul><h4 id="小代码-带有路径查找的迷你-shell" tabindex="-1">小代码：带有路径查找的迷你 Shell <a class="header-anchor" href="#小代码-带有路径查找的迷你-shell" aria-label="Permalink to &quot;小代码：带有路径查找的迷你 Shell&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const char *path = getenv(&quot;PATH&quot;);</span></span>
<span class="line"><span>    if (!path) path = &quot;(none)&quot;;</span></span>
<span class="line"><span>    printf(&quot;Current PATH:\\n%s\\n&quot;, path);</span></span>
<span class="line"><span>    setenv(&quot;PATH&quot;, &quot;/usr/local/bin:/usr/bin&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;\\nUpdated PATH:\\n%s\\n&quot;, getenv(&quot;PATH&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前路径：</span></span>
<span class="line"><span>/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>更新的路径：</span></span>
<span class="line"><span>/usr/local/bin:/usr/bin</span></span></code></pre></div><h4 id="第-10-步-为什么它很重要" tabindex="-1">第 10 步：为什么它很重要 <a class="header-anchor" href="#第-10-步-为什么它很重要" aria-label="Permalink to &quot;第 10 步：为什么它很重要&quot;">​</a></h4><p>环境变量为您的程序提供上下文：</p><ul><li>它们告诉您文件、库和配置的位置。</li><li>它们让您动态控制运行时行为。</li><li>它们对于系统工具、shell、守护进程和测试至关重要。</li></ul><p>了解如何读取和修改它们是掌握 C 语言 Unix 编程的关键。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>按字母顺序打印所有环境变量。</li><li>实现你自己的<code>env</code>C 中的命令。 3.编写程序修改<code>PATH</code>并启动另一个程序。</li><li>创建继承修改变量的子进程。</li><li>结合<code>setenv()</code>,<code>execle()</code>， 和<code>getenv()</code>模拟沙盒运行。</li></ol><p>接下来，您将了解错误处理和返回代码，这是每个 Unix 进程用来告诉系统它是成功还是失败的不可见信号。</p>`,63)])])}const b=a(t,[["render",i]]);export{r as __pageData,b as default};
